previewCss:
.darma-loader-darma-b14-bow-draw { --accent: var(--loader-color, #92400e); --accent-2: var(--loader-secondary-color, #dc2626); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .92); position: relative; }
.darma-loader-darma-b14-bow-draw .darma-loader-darma-b14-bow-draw__bow { position: absolute; left: 10%; top: 4%; width: 28%; height: 92%; border: calc(var(--loader-size, 116px) * .05) solid var(--accent); border-right: 0; border-radius: 66% 0 0 66% / 50% 0 0 50%; }
.darma-loader-darma-b14-bow-draw::before { content: ''; position: absolute; left: 36%; top: 4%; height: 92%; background: #475569; clip-path: polygon(0 0, 100% 49%, 0 100%, 0 96%, 93% 50%, 0 4%); animation: darma-loader-darma-b14-bow-draw-draw calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b14-bow-draw span { position: absolute; left: 34%; top: calc(50% - var(--loader-size, 116px) * .022); width: 46%; height: calc(var(--loader-size, 116px) * .044); border-radius: 999px; background: linear-gradient(180deg, #cbd5e1, #64748b); animation: darma-loader-darma-b14-bow-draw-release calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b14-bow-draw span::after { content: ''; position: absolute; left: 99%; top: calc(var(--loader-size, 116px) * -.032); width: calc(var(--loader-size, 116px) * .1); height: calc(var(--loader-size, 116px) * .1); background: var(--accent-2); clip-path: polygon(0 0, 100% 50%, 0 100%); }
.darma-loader-darma-b14-bow-draw span::before { content: ''; position: absolute; right: 97%; top: calc(var(--loader-size, 116px) * -.022); width: calc(var(--loader-size, 116px) * .08); height: calc(var(--loader-size, 116px) * .08); background: color-mix(in srgb, #000 16%, var(--accent-2)); clip-path: polygon(0 0, 100% 50%, 0 100%); }
@keyframes darma-loader-darma-b14-bow-draw-draw { 0%, 8% { width: 6%; } 44%, 54% { width: 30%; } 62%, 100% { width: 6%; } }
@keyframes darma-loader-darma-b14-bow-draw-release { 0%, 8% { opacity: 1; transform: translateX(0); } 44%, 54% { transform: translateX(20%); } 68% { opacity: 1; transform: translateX(calc(var(--loader-size, 116px) * .24)); } 76%, 100% { opacity: 0; transform: translateX(calc(var(--loader-size, 116px) * .3)); } }

